1644	      .select('id, total, status, garcom_id, gorjeta_valor, created_at')
1645	      .eq('restaurant_id', restaurantId)
1646	      .eq('canal', 'presencial')
1647	      .not('garcom_id', 'is', null)
1648	      .gte('created_at', de)
1649	      .lte('created_at', ate);
1650	
1651	    const orderIds = (pedidos ?? []).map((p: any) => p.id);
1652	    const { data: comissoes } = orderIds.length
1653	      ? await this.supabase.client
1654	          .from('garcom_comissoes_lancamentos')
1655	          .select('garcom_id, order_id, valor_calculado')
1656	          .in('order_id', orderIds)
1657	      : { data: [] as any[] };
1658	
1659	    const { data: comandasAtuais } = await this.supabase.client
1660	      .from('orders')
1661	      .select('id, garcom_id, status')
1662	      .eq('restaurant_id', restaurantId)
1663	      .eq('canal', 'presencial')
1664	      .not('garcom_id', 'is', null)
1665	      .in('status', this.COMANDA_STATUS_ABERTOS);
1666	
1667	    const porGarcom = new Map<number, any>();
1668	    for (const g of (garcons ?? []) as any[]) {
1669	      porGarcom.set(g.id, {
1670	        garcom_id: g.id,
1671	        nome: g.nome,
1672	        total_vendido: 0,
1673	        total_comissao: 0,
1674	        total_gorjeta: 0,
1675	        comandas_abertas: 0,
1676	        comandas_pendentes: 0,
1677	      });
1678	    }
1679	
1680	    for (const p of (pedidos ?? []) as any[]) {
1681	      if (p.status !== 'paga') continue;
1682	      const row = porGarcom.get(p.garcom_id);
1683	      if (!row) continue;
1684	      row.total_vendido += p.total ?? 0;
1685	      row.total_gorjeta += p.gorjeta_valor ?? 0;
1686	    }
1687	
1688	    for (const c of (comissoes ?? []) as any[]) {
1689	      const row = porGarcom.get(c.garcom_id);
1690	      if (!row) continue;
1691	      row.total_comissao += c.valor_calculado ?? 0;
1692	    }
1693	
1694	    for (const c of (comandasAtuais ?? []) as any[]) {
1695	      const row = porGarcom.get(c.garcom_id);
1696	      if (!row) continue;
1697	      if (c.status === 'aberta') row.comandas_abertas++;
1698	      if (c.status === 'fechada_garcom') row.comandas_pendentes++;
1699	    }
1700	
1701	    return { garcons: Array.from(porGarcom.values()) };
1702	  }
